import{_ as o,l as n,o as i,c as t,v as l,p as s,x as e,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"Focus drilling","description":"","frontmatter":{"title":"Focus drilling","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/focus-drilling.md","filePath":"litho/focus-drilling.md","lastUpdated":1789023840000}'),p={name:"litho/focus-drilling.md"};function h(u,a,g,A,B,f){const r=n("Mermaid");return i(),t("div",null,[a[1]||(a[1]=l('<h1 id="focus-drilling" tabindex="-1">Focus drilling <a class="header-anchor" href="#focus-drilling" aria-label="Permalink to &quot;Focus drilling&quot;">​</a></h1><div class="epigraph"><p>有时故意让同一点走过一段焦，用对比换焦深：窗在焦轴上被拉开，空中像不再是最佳焦点那一张。</p><footer>—— 据 Mack 对焦深与工艺窗的讨论，以及 SPIE 文献对 focus drilling 的通称整理</footer></div><p><a href="/litho/scanner-throughput">上一课</a>（扫描仪产能会计）。把剂量轴锁进闭环。缺口是：焦轴并不总是「越钉越尖」——厚胶、大地形、接触孔的可用焦深比光学瑞利焦深还要苛刻时，产线会故意走焦，把一场曝光摊在一段 \\(z\\) 上。本课钉 focus drilling。成像与分辨率这门课到此结束；记录介质从<a href="/litho/dnq-novolac">下一课</a>的 DNQ–Novolac 写起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>剂量环保证 \\(E\\) 进窗。调平环保证晶圆表面贴近最佳焦面。两者都默认：最佳焦是一个点，空中像取那一张。缺口出现在窗的焦轴太瘦、而片内地形或胶厚跨度比它更大的时候——植入层、厚胶、过孔，单焦点的 Bossung 在规格带里只剩一条缝。</p><p>Focus drilling 的答案是：同一场内让焦点扫过一个区间（分立的多次曝光，或扫描中连续走 \\(z\\)），每个晶圆点收到的是一段离焦空中像的剂量叠加。焦深被拉开，代价是调制下降，等效 NILS 变差。上一课刚钉住的剂量，往往还要加一点，才能把变钝的像再切到目标 CD。</p><h3 id="不是调平失败的美化名" tabindex="-1">不是调平失败的美化名 <a class="header-anchor" href="#不是调平失败的美化名" aria-label="Permalink to &quot;不是调平失败的美化名&quot;">​</a></h3><p>调平要把平均面放进窗；drilling 是在窗的定义上动手，故意加宽焦轴、收窄剂量轴。把 drilling 当成「台子调不平所以糊一把」，会把设备故障与工艺选择混在一起。本课默认调平是合格的，走焦是食谱。</p><p><span class="marginnote">名字来自 SPIE 与设备应用的通称，不是某篇独有发明。不要给它编造 arXiv 编号。Mack 把焦深与 E–D 窗讲清楚之后，这种「用对比买焦轴」的取舍是同一张图上的移动，而不是新的光学定律。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现大致三类：同一场分几次、每次偏一点焦再叠加剂量；扫描过程中工件台或镜头沿 \\(z\\) 调制；光学上用可调的焦深元件拉宽轴向响应。分立多次的权重要声明：等剂量分焦与中间多、两头少，叠出来的等效像不同。无论哪一种，前向模型都是：把若干离焦空中像按剂量权重相加，再进胶阈值。OPC 与邻近曲线必须用这张叠加像去校准，不能沿用最佳焦模型。isol 与 dense 的 Bossung 弯曲方向若相反，drilling 的权重会偏帮一方、伤害另一方，重叠窗仍可能为零。</p><p>表征仍用 Bossung / E–D：drilling 之后，CD 对 \\(z\\) 的曲线变平，对 \\(E\\) 的曲线变陡。曝光宽容度通常变差。要声明图形类别——密线、孤立线、孔的叠加权重不同，重叠窗可能被某一类先切死。</p><h3 id="何时值得买" tabindex="-1">何时值得买 <a class="header-anchor" href="#何时值得买" aria-label="Permalink to &quot;何时值得买&quot;">​</a></h3><p>地形高度差已经大于单焦点 DOF、而分辨率需求尚未顶死 \\(k_1\\) 地板时，drilling 常见。临界逻辑栅极少靠它过日子，因为对比预算更贵。本课不把「先进层都 drilling」写成道德。</p>',14)),(i(),s(E,null,{default:e(()=>[c(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z0%5B%22%E6%9C%80%E4%BD%B3%E7%84%A6%E7%82%B9%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20SUM%5B%22%E6%B2%BF%E7%84%A6%E8%BD%B4%E5%8A%A0%E6%9D%83%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20Z1%5B%22%E7%A6%BB%E7%84%A6%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20SUM%0A%20%20SUM%20--%3E%20NILSe%5B%22%E7%AD%89%E6%95%88%20NILS%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SUM%20--%3E%20DOF%5B%22%E7%84%A6%E8%BD%B4%E7%AA%97%E5%8F%A3%E6%8B%89%E5%BC%80%22%5D%0A%20%20NILSe%20--%3E%20EL%5B%22%E5%89%82%E9%87%8F%E8%BD%B4%E9%80%9A%E5%B8%B8%E6%94%B6%E7%AA%84%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离焦降低调制、改变侧瓣。若干张这样的像相加，阈值附近的斜率变缓，边缘对剂量更敏感，对 \\(z\\) 反而不那么敏感——因为本来就已经在「焦的混合物」里。线宽粗糙度往往变差：切在更缓的坡上，同样的剂量与化学噪声变成更大的边抖。孔的随机失效在 EUV 上会更明显；本课停在平均窗，不把光子泊松提前做完。厚胶层里，走焦还可以让底部与顶部都吃到「还算能用」的像，代价是整层对比都不是最佳——这与 DNQ 漂白补底部是不同机制，下一课化学会对照着读。</p><p>与上一课的关系：drilling 之后目标剂量常上移，闭环仍然要锁新的 \\(E\\)，只是工作点变了。狭缝扫描平均是 \\(y\\) 向光学指纹的平均；drilling 是 \\(z\\) 向像的平均。两个算子可以同时存在，不要混名。</p><p><span class="marginnote">双曝光 LELE 是两套掩模的位置问题；focus drilling 通常仍是同一张掩模、同一套图形。不要把「曝光两次」都叫做双重图形。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给某层必须 drilling 的纳米地形阈值，也不把某次 SPIE 演示的焦深倍数写成镜头规格。浸没流体与喷淋跟随是另一课。胶对比 \\(\\gamma\\) 会改变 drilling 之后还能不能切出陡壁，化学从下一课程开始——本课只要求后课在提「窗」时声明有没有走焦。</p><p>成像栏到此：波长、NA、\\(k_1\\)、邻近、转印、套刻、扫描、剂量、走焦，默认已经读完。下一课不再回头解释狭缝。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Focus drilling 故意沿焦轴叠加空中像，用对比换焦深。</li><li>剂量轴通常变瘦，目标 \\(E\\) 往往上移，闭环仍要锁。</li><li>OPC 必须用叠加像校准；最佳焦模型会系统性偏。</li><li>isol 与 dense 的叠加权重可能互伤，重叠窗仍可能为零。</li><li>与狭缝扫描平均正交：一个沿 \\(z\\)，一个沿扫描 \\(y\\)。</li><li>不是调平失败；默认调平合格，走焦是食谱。</li><li>成像与分辨率课程结束，下一课进入抗蚀剂化学。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；SPIE 对 focus drilling 的通称与设备应用公开讨论。</li></ul>',9))])}const D=o(p,[["render",h]]);export{m as __pageData,D as default};
